const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = "Gemini";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Colors
const P = "028090"; // Primary Teal
const S = "00A896"; // Secondary Seafoam
const A = "02C39A"; // Accent Mint
const D = "1E293B"; // Dark slate
const L = "F8FAFC"; // Light gray
const W = "FFFFFF"; // White

// Slide Master
pres.defineSlideMaster({
  title: 'TITLE_SLIDE',
  background: { color: P },
});

pres.defineSlideMaster({
  title: 'CONTENT_SLIDE',
  background: { color: L },
  objects: [
    { rect: { x: 0, y: 0, w: 10, h: 0.8, fill: { color: P } } },
    { rect: { x: 0, y: 5.3, w: 10, h: 0.325, fill: { color: P } } },
    { placeholder: { options: { name: 'title', type: 'title', x: 0.5, y: 0.1, w: 9, h: 0.6, fontSize: 24, fontFace: "Helvetica", bold: true, color: W, valign: 'middle' } } }
  ]
});

// SLIDE 1
let s1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
s1.addImage({ path: "/app/benchmark/assets/figure_1.jpg", x: 0, y: 0, w: 10, h: 5.625, sizing: { type: 'cover', w: 10, h: 5.625 }, transparency: 85 });
s1.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.5, w: 9, h: 2.5, fill: { color: "000000", transparency: 40 } });
s1.addText("SkillClaw: Let Skills Evolve Collectively with Agentic Evolver", { x: 1, y: 1.8, w: 8, h: 1, fontSize: 36, fontFace: "Helvetica", bold: true, color: W, align: "center", margin: 0 });
s1.addText("Collective Skill Evolution for Multi-User LLM Agent Ecosystems", { x: 1, y: 2.8, w: 8, h: 0.5, fontSize: 18, fontFace: "Helvetica", color: A, align: "center", margin: 0 });
s1.addText("Source: arxiv.org/abs/2604.08377", { x: 1, y: 3.4, w: 8, h: 0.3, fontSize: 14, fontFace: "Helvetica", color: S, align: "center", margin: 0 });

// SLIDE 2
let s2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
s2.addText("Agent Skills Remain Static After Deployment — Users Rediscover Solutions Independently", { placeholder: "title", fontSize: 20 });
// 2 Column layout
const getShadow = () => ({ type: "outer", color: "000000", blur: 6, offset: 2, angle: 45, opacity: 0.1 });
s2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 3.8, fill: { color: W }, shadow: getShadow() });
s2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 0.6, fill: { color: S } });
s2.addText("The Problem: Static Skills", { x: 0.7, y: 1.3, w: 3.8, h: 0.4, fontSize: 20, fontFace: "Helvetica", bold: true, color: W });
s2.addText([
  { text: "Manually installed skills never update from runtime experience.", options: { bullet: true, breakLine: true } },
  { text: "Failures and solutions are rediscovered repeatedly across users.", options: { bullet: true, breakLine: true } },
  { text: "No system-level knowledge accumulation.", options: { bullet: true } }
], { x: 0.7, y: 2.0, w: 3.8, h: 2.5, fontSize: 16, fontFace: "Helvetica", color: D, valign: "top" });

s2.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 1.2, w: 4.2, h: 3.8, fill: { color: W }, shadow: getShadow() });
s2.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 1.2, w: 4.2, h: 0.6, fill: { color: P } });
s2.addText("Limitations of Existing Methods", { x: 5.5, y: 1.3, w: 3.8, h: 0.4, fontSize: 20, fontFace: "Helvetica", bold: true, color: W });
s2.addText([
  { text: "Memory-based methods remain tied to specific instances and are hard to generalize.", options: { bullet: true, breakLine: true } },
  { text: "Skill-based methods compress experience into structured instructions but treat the resulting library as static.", options: { bullet: true } }
], { x: 5.5, y: 2.0, w: 3.8, h: 2.5, fontSize: 16, fontFace: "Helvetica", color: D, valign: "top" });

// SLIDE 3
let s3 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
s3.addText("Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution", { placeholder: "title", fontSize: 22 });
s3.addImage({ path: "/app/benchmark/assets/figure_1.jpg", x: 0.5, y: 1.2, w: 5, h: 3.5, sizing: { type: 'contain', w: 5, h: 3.5 } });
s3.addShape(pres.shapes.RECTANGLE, { x: 5.8, y: 1.2, w: 3.7, h: 3.8, fill: { color: W }, shadow: getShadow() });
s3.addText("Four Stages of Evolution", { x: 6.0, y: 1.4, w: 3.3, h: 0.4, fontSize: 20, fontFace: "Helvetica", bold: true, color: P });
s3.addText([
  { text: "1. Multi-user Interaction", options: { bold: true, breakLine: true } },
  { text: "   Agents produce structured session trajectories preserving action-feedback chains.", options: { breakLine: true, paraSpaceAfter: 5 } },
  { text: "2. Session Collection", options: { bold: true, breakLine: true } },
  { text: "   Trajectories are aggregated across users.", options: { breakLine: true, paraSpaceAfter: 5 } },
  { text: "3. Agentic Evolver", options: { bold: true, breakLine: true } },
  { text: "   Evidence → Attribution → Evolution.", options: { breakLine: true, paraSpaceAfter: 5 } },
  { text: "4. Skill Synchronization", options: { bold: true, breakLine: true } },
  { text: "   Verified skills merge to the shared repository.", options: {} }
], { x: 6.0, y: 1.9, w: 3.3, h: 2.8, fontSize: 13, fontFace: "Helvetica", color: D, valign: "top" });

// SLIDE 4
let s4 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
